try {
  const item = $input.first();
  const output = (item && item.json && item.json.output) ? String(item.json.output) : '';

  if (!output) return [{ json: { output: 'ERROR: AI Agent returned no output' } }];

  // Find [CHARTS_JSON] tag (with optional ** bold markers)
  const tagIdx = output.search(/\*{0,2}\[CHARTS_JSON\]\*{0,2}/);

  // If no tag found, try bracket-counting on raw output as fallback
  if (tagIdx === -1) {
    const start = output.indexOf('[');
    if (start !== -1) {
      let depth = 0, end = -1;
      for (let i = start; i < output.length; i++) {
        if (output[i] === '[') depth++;
        else if (output[i] === ']') { depth--; if (depth === 0) { end = i; break; } }
      }
      if (end !== -1) {
        try {
          const parsed = JSON.parse(output.slice(start, end + 1));
          const chartsJson = JSON.stringify(parsed);
          const analysis = output.slice(end + 1).trim();
          return [{ json: { output: '[CHARTS_JSON]' + chartsJson + '[/CHARTS_JSON]\n---ANALYSIS---\n' + analysis } }];
        } catch(_) {}
      }
    }
    return [{ json: { output } }];
  }

  // Get text after tag
  const after = output.slice(tagIdx).replace(/\*{0,2}\[CHARTS_JSON\]\*{0,2}/, '').trimStart();

  // Extract JSON array via bracket-counting
  const start = after.indexOf('[');
  if (start === -1) return [{ json: { output } }];

  let depth = 0, end = -1;
  for (let i = start; i < after.length; i++) {
    if (after[i] === '[') depth++;
    else if (after[i] === ']') { depth--; if (depth === 0) { end = i; break; } }
  }

  const rawChartsJson = end !== -1 ? after.slice(start, end + 1) : after.slice(start);

  let chartsJson;
  try {
    chartsJson = JSON.stringify(JSON.parse(rawChartsJson));
  } catch(_) {
    chartsJson = rawChartsJson;
  }

  const closeIdx = output.indexOf('[/CHARTS_JSON]');
  const analysis = closeIdx !== -1 ? output.slice(closeIdx + 14).trim() : '';

  return [{ json: { output: '[CHARTS_JSON]' + chartsJson + '[/CHARTS_JSON]\n---ANALYSIS---\n' + analysis } }];
} catch(e) {
  return [{ json: { output: 'ERROR: ' + e.message } }];
}
